#!/usr/bin/env bash
# Block until SLURM jobs reach a terminal state; report every transition and WHY it ended.
# Run it BACKGROUNDED: costs zero tokens while waiting, re-invokes you on exit.
#   Bash(run_in_background=true): ~/.claude/skills/work-log/bin/wait-job.sh 907111 907158
# Follows preempt-run.sh chains: a job that left the queue with a successor recorded in
# ~/.claude/state/preempt-chain/<job>.next is reported as resubmitted and its successor is waited on.
# Exit 0 = all COMPLETED; 1 = something failed/timed out/was cancelled; 64 = usage.
INT=${WAIT_JOB_INTERVAL:-300}; [ "$INT" -lt 300 ] && INT=300
C="$HOME/.claude/state/preempt-chain"
[ $# -ge 1 ] || { echo "usage: wait-job.sh <jobid> [jobid...]" >&2; exit 64; }

jobs=("$@"); declare -A prev lag; rc=0; live=1
while [ "$live" -eq 1 ]; do
  live=0
  for j in "${jobs[@]}"; do
    [ "${prev[$j]}" = "__done__" ] && continue
    st=$(squeue -j "$j" -h -o %T 2>/dev/null) || { live=1; continue; }   # squeue failed: unknown, retry
    st=$(printf '%s\n' "$st" | head -1)
    if [ -n "$st" ]; then                      # still queued or running
      if [ "${prev[$j]}" != "$st" ]; then
        r=$(squeue -j "$j" -h -o %r 2>/dev/null | head -1); [ "$r" = "None" ] && r=""
        echo "[$(date +%H:%M:%S)] job $j -> $st${r:+ ($r)}"
        prev[$j]=$st
      fi
      live=1
    else                                       # left the queue: get the verdict
      acc=$(sacct -j "$j" -n -X -o State,Elapsed,ExitCode 2>/dev/null)
      case "$(echo "$acc" | awk '{print $1}' | head -1)" in ''|PENDING|RUNNING|REQUEUED|SUSPENDED|COMPLETING)   # accounting lag: retry up to 3 rounds
        lag[$j]=$(( ${lag[$j]:-0} + 1 )); [ "${lag[$j]}" -le 3 ] && { live=1; continue; };; esac
      # array jobs: report the first non-COMPLETED task, if any
      read -r st el ex <<<"$(echo "$acc" | awk '$1!="COMPLETED"{print $1,$2,$3; f=1; exit} END{if(!f)print}' )"
      [ -n "$st" ] || read -r st el ex <<<"$(echo "$acc" | head -1 | awk '{print $1, $2, $3}')"
      nx=$(cat "$C/$j.next" 2>/dev/null)
      if [[ "$nx" =~ ^[0-9]+$ ]]; then
